  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');

const paragraphs = message.split(/\n+/).map((line) => line.trim()).filter(Boolean)
  .map((line) => `<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#334155;">${escapeHtml(line)}</p>`).join('');

const safeUrl = escapeHtml(resetUrl);
const htmlBody = `<!doctype html><html><body style="margin:0;padding:24px;background:#f8fafc;font-family:Arial,sans-serif;"><div style="max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:22px;overflow:hidden;box-shadow:0 14px 40px rgba(15,23,42,0.08);"><div style="padding:24px 28px;background:#5a1372;color:#ffffff;border-bottom:8px solid #fde75a;"><div style="font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:#fde75a;">Password Reset</div><h1 style="margin:10px 0 0;font-size:28px;line-height:1.2;font-weight:800;">${escapeHtml(subject)}</h1></div><div style="padding:28px;">${paragraphs}<div style="margin:26px 0 22px;"><a href="${safeUrl}" style="display:inline-block;background:#5a1372;color:#ffffff;text-decoration:none;padding:14px 24px;border-radius:12px;font-weight:700;font-size:15px;">Reset Password</a></div><div style="margin-top:28px;padding-top:18px;border-top:1px solid #e2e8f0;font-size:12px;line-height:1.6;color:#64748b;">Envisions Chess Academy LLP<br/>This secure link can only be used once.</div></div></div></body></html>`;

return [{ json: { to, subject, htmlBody, replyTo } }];

